//   warna/style hardcoded — sekarang di-strip agar ikut warna tema.
//   (2) Capability & Kerja Sama jadi accordion.
//   (3) Halaman baru: Link (/link) & Regulation (/regulation).
// PRASYARAT: jalankan SETELAH apply-dinamis, apply-navbar, apply-navbar-visual,
//            apply-fixes, apply-halaman, apply-halaman2.
// Cara pakai (dari root project):
//     node apply-halaman3.mjs
//     npm run dev     (WAJIB restart penuh — ada route baru)
// Aman dijalankan berkali-kali.

import { writeFileSync, mkdirSync } from 'node:fs';
import { dirname } from 'node:path';

const FILES = [
  ["src/lib/server/portal/transform.ts", ''],
  ["src/lib/components/shared/rich-content.svelte", ''],
  ["src/lib/server/db/schema.ts", ''],
  ["src/lib/types/content.ts", ''],
  ["src/lib/server/portal/queries.ts", ''],
  ["src/lib/data/nav.ts", ''],
  ["src/routes/capability/+page.svelte", ''],
  ["src/routes/kerjasama/+page.svelte", ''],
  ["src/routes/link/+page.server.ts", ''],
  ["src/routes/link/+page.svelte", ''],
  ["src/routes/regulation/+page.server.ts", ''],
  ["src/routes/regulation/+page.svelte", ''],
];

let ok = 0;
for (const [path, b64] of FILES) {
  try {
    mkdirSync(dirname(path), { recursive: true });
    writeFileSync(path, Buffer.from(b64, 'base64'));
    console.log('  ditulis:', path);
    ok++;
  } catch (e) {
    console.error('  GAGAL  :', path, '-', e.message);
  }
}
console.log('\nSelesai. ' + ok + '/' + FILES.length + ' file ditulis.');
console.log('Restart dev server (WAJIB, ada route baru): npm run dev');
console.log('Cek: buka Capability/HKI/Software Development di DARK mode — sekarang terbaca.');
console.log('Halaman baru: /link (Eksternal/Internal) & /regulation (3 kategori, tabel + cari).');
console.log('Sisa "Segera" tinggal: Jadwal Kereta Api & Jadwal Penerbangan.');
